"""Roman numeral conversion (1–3999)."""


def to_roman(n):
    """Convert an integer 1..3999 to its standard Roman numeral string."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("argument must be an integer")
    if not (1 <= n <= 3999):
        raise ValueError("n must be between 1 and 3999 inclusive")

    _lookup = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
    ]
    parts = []
    for value, symbol in _lookup:
        while n >= value:
            parts.append(symbol)
            n -= value
    return "".join(parts)


def from_roman(s):
    """Convert a standard Roman numeral string back to an integer."""
    if not isinstance(s, str) or not s:
        raise ValueError("input must be a non-empty string")

    _values = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    valid = set(_values)

    if any(ch not in valid for ch in s):
        raise ValueError("invalid character in numeral")

    # Reconstruct the canonical form and compare — this catches every
    # malformed input (IIII, VV, IC, XM, MMMM, etc.) in one shot.
    if to_roman(_from_roman_raw(s)) != s:
        raise ValueError("not a well-formed Roman numeral")

    return _from_roman_raw(s)


def _from_roman_raw(s):
    """Parse a Roman numeral string to int (no validation)."""
    total = 0
    prev = 0
    for ch in reversed(s):
        val = _values[ch]
        if val < prev:
            total -= val
        else:
            total += val
        prev = val
    return total

"""Tests for roman.py."""

import pytest
from roman import to_roman, from_roman


# ── to_roman: happy path ──────────────────────────────────────────────

class TestToRoman:
    def test_one(self):
        assert to_roman(1) == "I"

    def test_two(self):
        assert to_roman(2) == "II"

    def test_three(self):
        assert to_roman(3) == "III"

    def test_four(self):
        assert to_roman(4) == "IV"

    def test_five(self):
        assert to_roman(5) == "V"

    def test_nine(self):
        assert to_roman(9) == "IX"

    def test_forty(self):
        assert to_roman(40) == "XL"

    def test_forty_two(self):
        assert to_roman(42) == "XLII"

    def test_hundred_ninety_nine(self):
        assert to_roman(199) == "CXCIX"

    def test_two_thousand(self):
        assert to_roman(2000) == "MM"

    def test_max(self):
        assert to_roman(3999) == "MMMCMXCIX"

    @pytest.mark.parametrize("n", range(1, 4000))
    def test_roundtrip(self, n):
        assert from_roman(to_roman(n)) == n

    # ── to_roman: invalid input ───────────────────────────────────────

    def test_zero(self):
        with pytest.raises(ValueError):
            to_roman(0)

    def test_negative(self):
        with pytest.raises(ValueError):
            to_roman(-5)

    def test_above_range(self):
        with pytest.raises(ValueError):
            to_roman(4000)

    def test_float(self):
        with pytest.raises(ValueError):
            to_roman(3.14)

    def test_string(self):
        with pytest.raises(ValueError):
            to_roman("X")

    def test_none(self):
        with pytest.raises(ValueError):
            to_roman(None)

    def test_bool(self):
        with pytest.raises(ValueError):
            to_roman(True)


# ── from_roman: happy path ────────────────────────────────────────────

class TestFromRoman:
    def test_one(self):
        assert from_roman("I") == 1

    def test_three(self):
        assert from_roman("III") == 3

    def test_four(self):
        assert from_roman("IV") == 4

    def test_five(self):
        assert from_roman("V") == 5

    def test_nine(self):
        assert from_roman("IX") == 9

    def test_forty_two(self):
        assert from_roman("XLII") == 42

    def test_hundred_ninety_nine(self):
        assert from_roman("CXCIX") == 199

    def test_two_thousand(self):
        assert from_roman("MM") == 2000

    def test_max(self):
        assert from_roman("MMMCMXCIX") == 3999

    @pytest.mark.parametrize("n", range(1, 4000))
    def test_roundtrip(self, n):
        assert to_roman(from_roman(to_roman(n))) == n

    # ── from_roman: invalid inputs ────────────────────────────────────

    def test_iiii(self):
        with pytest.raises(ValueError):
            from_roman("IIII")

    def test_vv(self):
        with pytest.raises(ValueError):
            from_roman("VV")

    def test_ic(self):
        with pytest.raises(ValueError):
            from_roman("IC")

    def test_xm(self):
        with pytest.raises(ValueError):
            from_roman("XM")

    def test_mmmm(self):
        with pytest.raises(ValueError):
            from_roman("MMMM")

    def test_empty(self):
        with pytest.raises(ValueError):
            from_roman("")

    def test_banana(self):
        with pytest.raises(ValueError):
            from_roman("banana")

    def test_none(self):
        with pytest.raises(ValueError):
            from_roman(None)

    def test_int(self):
        with pytest.raises(ValueError):
            from_roman(42)

    def test_lower_case(self):
        with pytest.raises(ValueError):
            from_roman("iv")

    def test_trailing_i(self):
        with pytest.raises(ValueError):
            from_roman("VIIII")

    def test_il(self):
        with pytest.raises(ValueError):
            from_roman("IL")

    def test_xc_wrong(self):
        with pytest.raises(ValueError):
            from_roman("LXCV")

